func worker(ctx context.Context, jobs <-chan Job, results chan<- Result) {
  for {
    select {
    case <-ctx.Done():
      return
    case job, ok := <-jobs:
      if !ok { return }
      result := process(ctx, job)
      select {
      case <-ctx.Done(): return
      case results <- result:
      }
    }
  }
}

