async function runAgent(task, budget) {
  for (let step = 0; step < budget.maxSteps; step++) {
    if (budget.signal.aborted) throw new Error('Canceled');
    const next = await decideNext(task);
    if (next.type === 'done') return next.result;
    authorizeTool(next.tool, budget.actor);
    await executeWithTimeout(next, budget);
  }
  throw new Error('Step budget exceeded');
}

